            while (c <= ' ') {
                c = readByte();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -res : res;
        }
    }

